using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking Change 1: Discriminator property renamed from "Discriminator" to "$type" in 9.0.
        // Fix: Explicitly configure the old property name for backward compatibility with existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking Change 2: Id format changed from "EntityType|KeyValue" to just "KeyValue" in 9.0.
        // Fix: Use a value generator or shadow property to preserve the old format. Here we store id
        // with the old format by mapping the Id property explicitly.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);

        // Breaking Change 3: Cosmos DB provider no longer supports HasIndex() in 9.0.
        // Indexes in Cosmos are managed via indexing policy, not EF model configuration.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);

        // Breaking Change 4: Sync I/O now throws by default in 9.0.
        // Fix: See SyncJob.cs — converted to async, or opt back in below.
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // If sync I/O is still needed (e.g., legacy code), opt back in explicitly:
        // optionsBuilder.UseCosmos(...).ConfigureWarnings(w => w.Ignore(CosmosEventId.SyncNotSupported));
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

